"""PSR personal invite links: enrollment QR + HTTPS landing for volunteers."""

from __future__ import annotations

import os
import re
import time
from urllib.parse import quote, urlencode, urlparse

import jwt as pyjwt
from flask import Blueprint
from flask import current_app as app
from flask import jsonify, request
from flask_babel import gettext
from flask_security import auth_required, roles_accepted

from opentakserver.extensions import db, logger
from opentakserver.models.Token import Token
from opentakserver.models.user import User

psr_invite_api = Blueprint("psr_invite_api", __name__)

_HASH_RE = re.compile(r"^[0-9a-fA-F]{64}$")


def _host() -> str:
    try:
        return urlparse(request.url_root).hostname or "fts.plasmadancer.ru"
    except RuntimeError:
        return "fts.plasmadancer.ru"


def _invite_url(invite_code: str) -> str:
    # Short code (token_hash) — full JWT is too long for messengers and breaks links.
    return f"https://{_host()}/downloads/psr-invite.html?t={invite_code}"


def _qr_string(username: str, jwt_token: str, role: str = "SEARCHER") -> str:
    # Canonical ATAK/OTS enrollment deep link (also handled by ПСР TAK).
    # callsign=username so the map marker matches the OTS login.
    # role= is ПСР-only; ATAK ignores unknown query params.
    r = (role or "SEARCHER").strip() or "SEARCHER"
    u = quote(username)
    return (
        f"tak://com.atakmap.app/enroll?host={_host()}&username={u}"
        f"&token={quote(jwt_token)}&role={quote(r)}&callsign={u}"
    )


def _atak_callsign_pref(username: str) -> str:
    u = quote(username)
    return (
        f"tak://com.atakmap.app/preference?key1=locationCallsign&type1=string&value1={u}"
        f"&key2=callsign&type2=string&value2={u}"
    )


def _icu_url(username: str) -> str:
    host = _host()
    q = urlencode(
        {
            "address": host,
            "port": "8554",
            "protocol": "rtsp",
            "path": username,
            "username": username,
            "atak_address": host,
            "atak_port": "8089",
            "truststore_url": f"https://{host}/downloads/truststore-root.p12",
            "self_signed_cert": "true",
        }
    )
    return f"opentakicu://import?{q}"


def _tak_import_url() -> str:
    return (
        "tak://com.atakmap.app/import?url="
        + quote(f"https://{_host()}/downloads/psr-atak-config.zip", safe="")
    )


def _universal_config(username: str, role: str, tak: str, icu: str, invite_code: str) -> dict:
    host = _host()
    return {
        "version": 1,
        "kind": "psr-eud-config",
        "server": {
            "host": host,
            "cot_port": 8089,
            "cot_protocol": "ssl",
            "enrollment_port": 8446,
            "marti_https": 8443,
            "username": username,
            "callsign": username,
            "role": role,
        },
        "video": {
            "protocol": "rtsp",
            "host": host,
            "port": 8554,
            "rtsps_port": 8322,
            "path": username,
            "username": username,
            "publish_url": f"rtsp://{host}:8554/{username}",
        },
        "ca": {
            "truststore_url": f"https://{host}/downloads/truststore-root.p12",
            "password": "atakatak",
        },
        "links": {
            "https_invite": _invite_url(invite_code),
            "tak_enroll": tak,
            "tak_preference_callsign": _atak_callsign_pref(username),
            "tak_import_datapackage": _tak_import_url(),
            "icu_import": icu,
        },
    }


def _intent_url(tak_url: str, package: str) -> str:
    """Android Chrome-friendly Intent URL (bare tak:// is often blocked in-browser)."""
    # tak://com.atakmap.app/enroll?... → intent://com.atakmap.app/enroll?...#Intent;scheme=tak;package=...;end
    if "://" not in tak_url:
        return tak_url
    scheme, rest = tak_url.split("://", 1)
    invite_page = f"https://{_host()}/downloads/psr-invite.html"
    from urllib.parse import quote

    return (
        f"intent://{rest}#Intent;scheme={scheme};package={package};"
        f"S.browser_fallback_url={quote(invite_page, safe='')};end"
    )


def _payload(username: str, jwt_tok: str, invite_code: str, role: str = "SEARCHER") -> dict:
    role_u = (role or "SEARCHER").strip().upper() or "SEARCHER"
    if role_u not in ("SEARCHER", "LEAD", "FIELD_HQ"):
        role_u = "SEARCHER"
    tak = _qr_string(username, jwt_tok, role_u)
    icu = _icu_url(username)
    cfg = _universal_config(username, role_u, tak, icu, invite_code)
    return {
        "success": True,
        "username": username,
        "callsign": username,
        "role": role_u,
        "config": cfg,
        "apps": {
            "pss_tak": {
                "label": "ПСР TAK",
                "package": "ru.plasmadancer.psr.tak",
                "deeplink": tak,
                "intent": _intent_url(tak, "ru.plasmadancer.psr.tak"),
            },
            "atak_civ": {
                "label": "ATAK CIV",
                "package": "com.atakmap.app.civ",
                "deeplink": tak,
                "intent": _intent_url(tak, "com.atakmap.app.civ"),
                "preference": _atak_callsign_pref(username),
                "datapackage": f"https://{_host()}/downloads/psr-atak-config.zip",
                "import": _tak_import_url(),
            },
            "psr_icu": {
                "label": "ПСР Видео",
                "package": "ru.plasmadancer.psr.icu",
                "deeplink": icu,
                "intent": _intent_url(icu, "ru.plasmadancer.psr.icu"),
            },
            "opentak_icu": {
                "label": "OpenTAK ICU",
                "package": "io.opentakserver.opentakicu",
                "deeplink": icu,
                "intent": _intent_url(icu, "io.opentakserver.opentakicu"),
            },
        },
        "qr_pref_callsign": _atak_callsign_pref(username),
        "intent_atak_callsign": _intent_url(_atak_callsign_pref(username), "com.atakmap.app.civ"),
        "invite_url": _invite_url(invite_code),
        "qr_string": tak,
        "qr_icu": icu,
        "intent_pss": _intent_url(tak, "ru.plasmadancer.psr.tak"),
        "intent_atak": _intent_url(tak, "com.atakmap.app.civ"),
        "intent_icu": _intent_url(icu, "ru.plasmadancer.psr.icu"),
        "intent_icu_stock": _intent_url(icu, "io.opentakserver.opentakicu"),
        "invite_code": invite_code,
        "ca_password": "atakatak",
        "hint": "Пароль учётной записи OTS сообщает штаб отдельно (не в ссылке).",
        "server": {
            "host": _host(),
            "cot_ssl": 8089,
            "enrollment": 8446,
            "rtsp": 8554,
            "rtsps": 8322,
        },
        "downloads": {
            "truststore": f"https://{_host()}/downloads/truststore-root.p12",
            "atak_config": f"https://{_host()}/downloads/psr-atak-config.zip",
            "field_kit": f"https://{_host()}/downloads/psr-field-kit.zip",
            "pss_tak": f"https://{_host()}/downloads/PSS-TAK-latest.apk",
            "icu": f"https://{_host()}/downloads/OpenTAK_ICU-PSR-latest.apk",
            "connect_txt": f"https://{_host()}/downloads/psr-connect.txt",
            "config_json": f"https://{_host()}/api/psr/invite?t={invite_code}&format=config",
        },
    }


def _ensure_token(username: str, body: dict) -> Token:
    row = db.session.execute(db.session.query(Token).filter_by(username=username)).first()
    token = row[0] if row else None
    if not token:
        token = Token()
        token.creation = int(time.time())
    expiration = body.get("exp")
    if expiration is not None:
        expiration = int(expiration)
        if expiration > 2147483647:
            expiration = expiration / 1000
        token.expiration = expiration
    not_before = body.get("nbf")
    if not_before is not None:
        not_before = int(not_before)
        if not_before > 2147483647:
            not_before = not_before / 1000
        token.not_before = not_before
    if body.get("max"):
        try:
            max_uses = int(body.get("max"))
            if max_uses > 0:
                token.max_uses = max_uses
        except (TypeError, ValueError):
            pass
    # Default: usable for ~90 days if no exp provided (helps enrollment QR too)
    if token.expiration is None and body.get("exp") is None:
        token.expiration = int(time.time()) + 90 * 24 * 3600
    if token.max_uses is None and not body.get("max"):
        token.max_uses = 20
    token.username = username
    token.disabled = False
    token.hash_token()
    db.session.add(token)
    db.session.commit()
    return token


def _resolve_token_row(raw: str) -> tuple[Token | None, str | None]:
    """Return (token_row, jwt_for_qr). Accepts short hash or full JWT."""
    raw = (raw or "").strip()
    if not raw:
        return None, None

    if _HASH_RE.match(raw):
        row = db.session.query(Token).filter_by(token_hash=raw).first()
        if not row or row.disabled:
            return None, None
        return row, row.generate_token()

    # Legacy: full JWT in query string
    pub = os.path.join(
        app.config.get("OTS_CA_FOLDER"), "certs", "opentakserver", "opentakserver.pub"
    )
    with open(pub, "r") as key:
        decoded = pyjwt.decode(raw, key.read(), algorithms=["RS256"], audience="OpenTAKServer")
    username = decoded.get("sub")
    if not username:
        return None, None
    row = db.session.query(Token).filter_by(username=username).first()
    if not row or row.disabled:
        return None, None
    return row, raw


@psr_invite_api.route("/api/psr/invite", methods=["POST"])
@auth_required()
@roles_accepted("administrator")
def create_invite():
    """Admin: create/refresh enrollment token and return personal HTTPS invite URL."""
    body = request.get_json(silent=True) or {}
    username = (body.get("username") or "").strip()
    if not username:
        return jsonify({"success": False, "error": gettext("username required")}), 400
    user = db.session.query(User).filter_by(username=username).first()
    if not user:
        return jsonify({"success": False, "error": gettext("No such user: %(u)s", u=username)}), 404
    try:
        token = _ensure_token(username, body)
        jwt_tok = token.generate_token()
        hint_password = body.get("password_hint")
        role = (body.get("role") or "SEARCHER")
        out = _payload(username, jwt_tok, token.token_hash, role=role)
        out["password_hint"] = hint_password if hint_password else None
        # Do not put JWT in invite_url; keep in response for ATAK QR if needed
        out["token"] = jwt_tok
        return jsonify(out)
    except Exception as e:
        logger.error("psr invite create failed: %s", e)
        return jsonify({"success": False, "error": str(e)}), 400


@psr_invite_api.route("/api/psr/invite", methods=["GET"])
def resolve_invite():
    """Public: resolve invite by short hash (preferred) or legacy JWT. No cookie."""
    raw = (request.args.get("t") or request.args.get("token") or "").strip()
    if not raw:
        return jsonify({"success": False, "error": gettext("token required")}), 400
    try:
        token_row, jwt_tok = _resolve_token_row(raw)
        if not token_row or not jwt_tok:
            return jsonify({"success": False, "error": gettext("Token disabled or missing")}), 404
        out = _payload(token_row.username, jwt_tok, token_row.token_hash)
        if (request.args.get("format") or "").strip().lower() == "config":
            return jsonify(out.get("config") or {})
        return jsonify(out)
    except Exception as e:
        logger.error("psr invite resolve failed: %s", e)
        return jsonify({"success": False, "error": gettext("Invalid or expired token")}), 400
